    assert_eq!(field(&result, "bytes"), &Value::I64(300_000));
    assert_eq!(
        field(&result, "sha256"),
        &Value::String(hex_sha256(&body))
    );
    assert_eq!(field(&result, "reused"), &Value::Bool(false));
    assert_eq!(entries(&target.parent().unwrap()), vec!["model.bin"]);
    server.join().unwrap();
}

